fn longest_increasing_subsequence(nums: &Vec<i32>) -> (max: i32)
    requires
        1 <= nums.len() <= 2500,
        forall|i: int| 0 <= i < nums.len() ==> #[trigger] nums[i] >= -10000 && #[trigger] nums[i] <= 10000,

    ensures
        max >= 1,
{
    // Length of the longest strictly increasing run of adjacent elements.
    let mut best: i32 = 1;
    let mut run: i32 = 1;
    let mut i: usize = 1;
    while i < nums.len()
        invariant
            1 <= i <= nums.len(),
            nums.len() <= 2500,
            1 <= run <= i,
            1 <= best <= i,
        decreases nums.len() - i,
    {
        if nums[i - 1] < nums[i] {
            run = run + 1;
        } else {
            run = 1;
        }
        if run > best {
            best = run;
        }
        i = i + 1;
    }
    best
}
